    return JSON.stringify([
      metric.id,
      metric.version,
      resolveEffectiveLeafWeights(metric.id, metrics).filter((leaf) => leaf.effectiveWeight > 0).map((leaf) => [leaf.effectiveWeight, metricSignature(metrics.get(leaf.rawMetricId))])
    ]);
